#include <iostream>
#include <vector>

using namespace std;

/**
 * Problem: 10517 - Hartals
 * 
 * 解題思路：
 * 1. 模擬 N 天內的罷工情況。
 * 2. 給定 P 個政黨，每個政黨有自己的罷工週期 h_i。
 * 3. 罷工規則：
 *    - 第 d 天如果有政黨的週期 h_i 能整除 d，則該天可能有罷工。
 *    - 每週的週五（第 6, 13, 20... 天）和週六（第 7, 14, 21... 天）不罷工。
 *    - 如果一天有多個政黨罷工，只計算一次。
 * 4. 判斷週五週六：d % 7 == 6 (週五) 或 d % 7 == 0 (週六)。
 */

int solve() {
    int n, p;
    if (!(cin >> n)) return -1;
    cin >> p;
    vector<int> h(p);
    for (int i = 0; i < p; ++i) cin >> h[i];

    int count = 0;
    for (int d = 1; d <= n; ++d) {
        // 檢查是否為週五或週六
        if (d % 7 == 6 || d % 7 == 0) continue;

        bool strike = false;
        for (int i = 0; i < p; ++i) {
            if (d % h[i] == 0) {
                strike = true;
                break;
            }
        }
        if (strike) count++;
    }
    return count;
}

int main() {
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int result = solve();
        if (result != -1) {
            cout << result << endl;
        }
    }
    return 0;
}
